from markupsafe import Markup
ARC = '<g id="arc" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round"><path d="M32 10A22 22 0 0 1 53.7 35.8"/><polygon points="57.6,36.5 49.8,35.1 52.7,41.7" fill="#fff" stroke="none"/></g>'
LOGO = Markup('<svg class="logo" viewBox="0 0 64 64"><defs><linearGradient id="lg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f472b6"/><stop offset=".5" stop-color="#8b5cf6"/><stop offset="1" stop-color="#06b6d4"/></linearGradient>' + ARC + '</defs><circle cx="32" cy="32" r="30" fill="url(#lg)"/><g class="spin"><use href="#arc"/><use href="#arc" transform="rotate(120 32 32)"/><use href="#arc" transform="rotate(240 32 32)"/></g><text x="32" y="40" text-anchor="middle" font-family="Arial Black,Arial" font-weight="900" font-size="21" fill="#fff">R</text></svg>')
ICON = {"Electrical Appliances":"🔌","Books":"📚","Drafters":"📐","Dresses":"👗","Jewellery":"💍","Handmade/Creative":"🎨","Other":"📦"}
GRAD = {"Electrical Appliances":"linear-gradient(135deg,#f59e0b,#ef4444)","Books":"linear-gradient(135deg,#3b82f6,#6366f1)","Drafters":"linear-gradient(135deg,#10b981,#06b6d4)","Dresses":"linear-gradient(135deg,#ec4899,#8b5cf6)","Jewellery":"linear-gradient(135deg,#eab308,#f97316)","Handmade/Creative":"linear-gradient(135deg,#14b8a6,#84cc16)","Other":"linear-gradient(135deg,#64748b,#334155)"}
KEYS = [("casio","🧮"),("laptop","💻"),("adapter","🔌"),("drafter","📐"),("speaker","🔊"),("iron","♨️"),("saree","🥻"),("coat","🥼"),("blazer","🧥"),("necklace","📿"),("bat","🏏"),("backpack","🎒"),("racket","🏸"),("mat","🧘"),("candle","🕯️"),("canvas","🖼️"),("tent","⛺")]
def icon(t, c):
    t = t.lower()
    for k, e in KEYS:
        if k in t: return e
    return ICON.get(c, "📦")
CSS = """:root{--p:#7c3aed;--t:#0891b2;--ink:#1e1b4b}*{box-sizing:border-box}body{margin:0;font-family:'Segoe UI',Arial,sans-serif;color:var(--ink);background:linear-gradient(135deg,#4f46e5,#0ea5e9 50%,#10b981) fixed;min-height:100vh}
.logo{width:42px;height:42px;filter:drop-shadow(0 2px 6px #0004)}.spin{transform-box:fill-box;transform-origin:center;animation:sp 14s linear infinite}@keyframes sp{to{transform:rotate(360deg)}}
.top{position:sticky;top:0;z-index:5;background:#ffffff26;backdrop-filter:blur(14px);padding:8px 14px;display:flex;align-items:center;gap:12px;color:#fff;border-bottom:1px solid #fff4}.top b{font-size:22px;letter-spacing:2px;margin-right:auto}.top small{font-weight:400;font-size:10px;letter-spacing:1px;display:block}.top a{color:#fff;text-decoration:none;font-size:13px;font-weight:600}
main{max-width:820px;margin:0 auto;padding:12px 12px 100px}h2,h3.h{color:#fff;text-shadow:0 2px 6px #0003}.card{background:#ffffffee;border-radius:20px;padding:16px;margin:12px 0;box-shadow:0 8px 24px #0002}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px}.grid .card{margin:0}.item{text-decoration:none;color:var(--ink);transition:.2s}.item:hover{transform:translateY(-6px) scale(1.02)}
.pic{height:90px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:48px;margin-bottom:8px}.pic.big{height:140px;font-size:80px}.item h4{margin:4px 0}.m{margin:2px 0;color:#64748b;font-size:12px}
.cats{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:10px}.cat{border-radius:18px;padding:14px 6px;text-align:center;color:#fff;font-weight:700;font-size:13px;text-decoration:none;box-shadow:0 6px 16px #0003;transition:.2s}.cat:hover{transform:rotate(-2deg) scale(1.06)}.cat span{display:block;font-size:34px}
input,select,textarea,button{width:100%;padding:11px;margin:5px 0;border:1px solid #c7d2fe;border-radius:12px;font:inherit}button,.btn{background:linear-gradient(135deg,var(--p),var(--t));color:#fff;border:0;cursor:pointer;text-decoration:none;display:inline-block;padding:10px 16px;border-radius:12px;width:auto;font-weight:600}
.btn.sm,button.sm{padding:6px 12px;font-size:13px}.ghost{background:#e2e8f0!important;color:#334155!important}.red{background:#ef4444!important}
.tag{background:#ede9fe;color:#5b21b6;padding:3px 9px;border-radius:12px;font-size:12px;font-weight:600}.warn{background:#fef3c7;border-left:5px solid #f59e0b;padding:10px;border-radius:10px}
.flash{background:#dbeafe;padding:10px;border-radius:12px;margin:8px 0}.alert{background:#fde68a;border-radius:14px;padding:12px;margin:8px 0;font-weight:600;animation:pulse 2s infinite}.alert.bad{background:#fecaca}@keyframes pulse{50%{transform:scale(1.015)}}
.me{background:#ddd6fe;margin-left:30%}.msg{padding:8px 12px;border-radius:14px;margin:6px 0;background:#e5e7eb}img,video{max-width:100%;border-radius:12px}.inl{display:flex;gap:10px;flex-wrap:wrap}.inl>*{flex:1;min-width:140px}
.choice button{width:100%;font-size:18px;padding:18px}.choice small{display:block;font-weight:400}table{width:100%;border-collapse:collapse}td{padding:6px;border-bottom:1px solid #e2e8f0}td:first-child{color:#64748b;width:40%}
.tabs{position:fixed;bottom:0;left:0;right:0;background:#ffffffee;backdrop-filter:blur(12px);display:flex;justify-content:space-around;padding:8px 0;box-shadow:0 -4px 16px #0003;z-index:5}.tabs a{text-align:center;text-decoration:none;color:#475569;font-size:11px;font-weight:600}.tabs a span{display:block;font-size:22px}
.ov{position:fixed;inset:0;background:#000a;z-index:20;display:flex;align-items:center;justify-content:center}.modal{background:#fff;border-radius:22px;padding:22px;width:90%;max-width:380px;animation:pop .4s}@keyframes pop{from{transform:scale(.6);opacity:0}}
.auth{max-width:420px;margin:5vh auto;padding:0 14px}.hero{text-align:center;color:#fff}.hero .logo{width:90px;height:90px}.hero h1{margin:0;font-size:46px;letter-spacing:6px}.hero p{margin:4px 0 14px;letter-spacing:2px}
details{background:#f5f3ff;border-radius:12px;padding:10px;margin:8px 0}summary{cursor:pointer;font-weight:700}ol.steps li{margin:8px 0}"""
BASE = """<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>RBR - Rent Borrow Reuse</title><style>""" + CSS + """</style></head><body>
{% if me() %}<div class=top>{{LOGO}}<b>RBR<small>RENT · BORROW · REUSE</small></b><a href="/missing">🔎 Missing</a><a href="/complaints">🚨 Complaints</a><a href="/help">❓ Help</a><a href="/logout">Logout</a></div>
<main>{% with m=get_flashed_messages() %}{% for x in m %}<div class=flash>{{x}}</div>{% endfor %}{% endwith %}
{% for r in rem %}<div class="alert {{'bad' if r.left<0}}">{% if r.left<0 %}🚨 Deadline over! Return <b>{{r.title}}</b> to {{r.oname}} now.{% else %}⏰ Reminder: return <b>{{r.title}}</b> to {{r.oname}} by {{r.due}} ({{r.left}} day(s) left).{% endif %}</div>{% endfor %}
{% block b %}{% endblock %}</main>
<div class=tabs><a href="/"><span>🏠</span>Home</a><a href="/dash/rent"><span>💰</span>Rent</a><a href="/dash/borrow"><span>🤝</span>Borrow</a><a href="/add"><span>➕</span>Upload</a><a href="/profile"><span>👤</span>Profile</a></div>
{% if rev %}<div class=ov><div class=modal><h3>⭐ Item returned!</h3><p>The owner received <b>{{rev.title}}</b>. Please review it:</p><form method=post action="/review/{{rev.id}}"><select name=rating><option value=5>⭐⭐⭐⭐⭐ Excellent</option><option value=4>⭐⭐⭐⭐ Good</option><option value=3>⭐⭐⭐ Okay</option><option value=2>⭐⭐ Poor</option><option value=1>⭐ Bad</option></select><textarea name=text placeholder="Your review (optional)"></textarea><button>Submit review</button></form><form method=post action="/review/{{rev.id}}/skip"><button class="ghost">Skip</button></form></div></div>{% endif %}
{% else %}<div class=auth><div class=hero>{{LOGO}}<h1>RBR</h1><p>RENT · BORROW · REUSE</p></div>{% with m=get_flashed_messages() %}{% for x in m %}<div class=flash>{{x}}</div>{% endfor %}{% endwith %}{% block a %}{% endblock %}</div>{% endif %}</body></html>"""
def P(x): return '{% extends "base.html" %}{% block b %}' + x + '{% endblock %}'
def A(x): return '{% extends "base.html" %}{% block a %}' + x + '{% endblock %}'
LEFT = "{% if r.status=='active' %}<br><small>Due <b>{{r.due}}</b> · {{'🚨 OVERDUE by '~(-r.left)~' day(s)' if r.left<0 else r.left~' day(s) left'}}</small>{% endif %}"
T = {"base.html": BASE,
"login.html": A("""<div class=card><h3>Login</h3><form method=post><input name=email type=email placeholder=Email required><input name=pw type=password placeholder=Password required><button style="width:100%">Login</button></form><p>New here? <a href="/register">Register with your college ID</a></p><p class=m>Demo: demo1@rbr.in / demo123</p></div>"""),
"register.html": A("""<div class=card><h3>Campus Registration</h3><form method=post enctype=multipart/form-data><input name=name placeholder="Full name" required><input name=phone placeholder="Phone number (10 digits)" required pattern="[0-9]{10}"><input name=email type=email placeholder="Email ID" required><input name=pw type=password placeholder="Password" required>
<div class=inl><select name=gender><option>Male</option><option>Female</option><option>Other</option></select><select name=year><option>1st year</option><option>2nd year</option><option>3rd year</option><option>4th year</option></select></div><input name=location id=loc placeholder="Location (allow access to auto-fill)">
<label>📇 Upload clear college ID - RBR checks it:</label><input type=file name=idproof accept="image/*" required><button style="width:100%">Register &amp; Enter RBR</button></form><p>Already registered? <a href="/login">Login</a></p></div>
<script>navigator.geolocation&&navigator.geolocation.getCurrentPosition(p=>loc.value=p.coords.latitude.toFixed(4)+','+p.coords.longitude.toFixed(4))</script>"""),
"home.html": P("""<form class=card method=get><input name=q value="{{s}}" placeholder="🔍 Search items inside campus..."><input type=hidden name=cat value="{{c}}"></form>
{% if not s and not c %}<h3 class=h>Categories</h3><div class=cats>{% for k in CATS %}<a class=cat style="background:{{GRAD[k]}}" href="/?cat={{k}}"><span>{{ICON[k]}}</span>{{k}}</a>{% endfor %}</div>{% endif %}
<h3 class=h>{{c or 'Available items'}} {% if c or s %}<a href="/" class=tag>✕ clear</a>{% endif %}</h3><div class=grid>{% for i in items %}<a class="card item" href="/item/{{i.id}}"><div class=pic style="background:{{GRAD[i.cat]}}">{{icon(i.title,i.cat)}}</div><h4>{{i.title}}</h4><p class=m>{{i.brand}} · bought {{i.bought_on}}</p><p><b>Rs.{{i.price}}/day</b></p><span class=tag>👥 {{i.rc}} requested</span></a>{% else %}<div class=card>No items here yet. Tap ➕ Upload!</div>{% endfor %}</div>"""),
"item.html": P("""<div class=card><div class=pic big style="background:{{GRAD[it.cat]}}">{{icon(it.title,it.cat)}}</div><h2 style="color:#1e1b4b;text-shadow:none">{{it.title}}</h2>
<table><tr><td>Item name</td><td>{{it.title}}</td></tr><tr><td>Brand</td><td>{{it.brand}}</td></tr><tr><td>Bought on</td><td>{{it.bought_on}}</td></tr><tr><td>Condition</td><td>{{it.cond}}</td></tr><tr><td>Category</td><td>{{it.cat}}</td></tr><tr><td>Owner</td><td>{{it.oname}}</td></tr><tr><td>Rent</td><td>Rs.{{it.price}} / day</td></tr><tr><td>Borrow</td><td>Free (max 7 days)</td></tr><tr><td>Members requested</td><td><span class=tag>👥 {{rc}}</span></td></tr><tr><td>Rating</td><td>{{ ('⭐ %.1f (%d reviews)'|format(rv.a,rv.n)) if rv.n else 'No reviews yet' }}</td></tr></table>
<p>{{it.descr}}</p>{% if it.video %}<video controls src="/static/uploads/{{it.video}}"></video>{% endif %}</div>
{% if it.owner==me().id %}<div class=card>This is your item.</div>{% elif not it.available %}<div class=card>🔒 This item is currently rented out.</div>{% else %}<div class=card><h3>How do you want it?</h3><div class="inl choice">
{% if it.avail in ('both','rent') %}<form method=post action="/request/{{it.id}}"><input type=hidden name=mode value=rent><button>💰 Rent<small>Rs.{{it.price}}/day</small></button></form>{% endif %}
{% if it.avail in ('both','borrow') %}<form method=post action="/request/{{it.id}}"><input type=hidden name=mode value=borrow><button style="background:linear-gradient(135deg,#10b981,#06b6d4)">🤝 Borrow<small>Free · max 7 days</small></button></form>{% endif %}</div></div>{% endif %}
<div class=warn><b>Safety cautions</b><ul>{% for c in CAUTIONS %}<li>{{c}}</li>{% endfor %}</ul></div>"""),
"dash.html": P("""<h2>{{'💰 Rent Dashboard' if mode=='rent' else '🤝 Borrow Dashboard'}}</h2>
<h3 class=h>📥 Requests on my items (merchant history)</h3>{% for r in got %}<div class=card><b>{{r.title}}</b> ← {{r.cname}} <span class=tag>{{r.status}}</span>{% if mode=='rent' and r.days %} · {{r.days}} days = Rs.{{r.days*r.price}}{% endif %}""" + LEFT + """<br>
{% if r.status=='pending' %}<form method=post action="/accept/{{r.id}}" style="display:inline"><button class=sm>Accept</button></form> <form method=post action="/decline/{{r.id}}" style="display:inline"><button class="sm ghost">Decline</button></form>
{% elif r.status=='accepted' %}<small>Waiting for {{r.cname}} to enter number of days...</small>
{% elif r.status=='active' %}<a class="btn sm" href="/chat/{{r.id}}">💬 Chat</a> <form method=post action="/received/{{r.id}}" style="display:inline"><button class="sm" style="background:#16a34a">✅ Received</button></form>
{% elif r.status=='closed' %}<small>✅ Received on {{r.received_at}}</small>{% endif %}</div>{% else %}<div class=card>No requests yet.</div>{% endfor %}
<h3 class=h>📤 My requests</h3>{% for r in mine %}<div class=card><b>{{r.title}}</b> ({{r.brand}}) · owner {{r.oname}} <span class=tag>{{r.status}}</span>""" + LEFT + """<br>
{% if r.status=='accepted' %}<div class=warn>🎉 Accepted! How many days will you use it? ({{'max 7' if mode=='borrow' else 'max 30'}})<form method=post action="/days/{{r.id}}" class=inl><input name=days type=number min=1 max="{{7 if mode=='borrow' else 30}}" required><button>Start &amp; open chat</button></form></div>
{% elif r.status=='active' %}<a class="btn sm" href="/chat/{{r.id}}">💬 Chat</a>{% elif r.status=='pending' %}<small>Waiting for the owner to accept...</small>{% elif r.status=='declined' %}<small>Not selected</small>{% endif %}</div>{% else %}<div class=card>You have not requested anything in {{mode}} mode.</div>{% endfor %}"""),
"chat.html": P("""<div class=card><h3>💬 {{rq.title}}</h3><p class=m>Owner {{rq.oname}} · Renter {{rq.cname}} · {{rq.days}} day(s) · Return by <b>{{rq.due}}</b></p>{% for m in ms %}<div class="msg {{'me' if m.sender==me().id}}"><b>{{m.name}}</b> <small>{{m.ts}}</small><br>{{m.body}}</div>{% endfor %}
{% if rq.handover_photo %}<p>Handover photo:</p><img src="/static/uploads/{{rq.handover_photo}}" width=150>{% endif %}
{% if rq.closed %}<p class=warn>Chat closed - item received on {{rq.received_at}}.</p>{% else %}<form method=post enctype=multipart/form-data><input name=body placeholder="Type a message"><button>Send</button>{% if me().id==rq.owner %}<label>📸 Handover photo of the renter (for safety):</label><input type=file name=handover accept="image/*">{% endif %}</form>
{% if me().id==rq.owner %}<form method=post action="/received/{{rq.id}}"><button style="background:#16a34a">✅ Item returned - Received</button></form>{% endif %}{% endif %}</div>"""),
"add.html": P("""<div class=card><h3>➕ Upload an item</h3><form method=post enctype=multipart/form-data><input name=title placeholder="Item name (e.g. Casio fx-991EX)" required><input name=brand placeholder="Brand" required>
<select name=cat onchange="t.style.display=this.value=='Electrical Appliances'?'block':'none'">{% for k in CATS %}<option>{{k}}</option>{% endfor %}</select>
<div class=inl><div><label>Bought on</label><input type=date name=bought_on required></div><div><label>Condition</label><select name=cond><option>Like new</option><option>Used (2nd hand)</option></select></div></div>
<div class=inl><input name=price type=number min=0 placeholder="Rent Rs. per day" required><select name=avail><option value=both>Rent + Borrow</option><option value=rent>Rent only</option><option value=borrow>Borrow only (free)</option></select></div>
<textarea name=descr placeholder="How it works, rules..."></textarea><label>🎥 Video showing how it works</label><input type=file name=video accept="video/*">
<div id=t class=warn style="display:none"><b>Working test (all must pass):</b>{% for c in CHECKS %}<br><label><input type=checkbox name=chk value=1 style="width:auto"> {{c}}</label>{% endfor %}</div><button style="width:100%">Publish</button></form></div>"""),
"profile.html": P("""<div class=card><h2 style="color:#1e1b4b;text-shadow:none">{{me().name}}</h2>{% if me().photo %}<img src="/static/uploads/{{me().photo}}" width=130>{% endif %}<p>{{me().gender}} · {{me().year}} · {{me().email}}</p><span class=tag>{{me().id_status}}</span>
<form method=post enctype=multipart/form-data><label>Profile photo (photo only)</label><input type=file name=photo accept="image/*"><button>Upload photo</button></form></div>
<h3 class=h>My uploads</h3>{% for i in mine %}<div class=card>{{icon(i.title,i.cat)}} <b>{{i.title}}</b> · {{i.brand}} <span class=tag>{{'visible' if i.available else 'rented out - hidden'}}</span></div>{% else %}<div class=card>Nothing uploaded yet.</div>{% endfor %}"""),
"complaints.html": P("""<div class=card><h3>🚨 Report item not returned</h3>{% if mine %}<form method=post><select name=req>{% for r in mine %}<option value="{{r.id}}">{{r.title}} (request #{{r.id}})</option>{% endfor %}</select><textarea name=text placeholder="What happened?"></textarea><button>Post as suspect + inform campus police</button></form>{% else %}<p>Items you have lent out (with active rentals) can be reported here.</p>{% endif %}</div>
<h3 class=h>Public suspect list</h3>{% for c in cs %}<div class=card>{% if c.handover_photo %}<img src="/static/uploads/{{c.handover_photo}}" width=110>{% endif %}<p><b>{{c.suspect}}</b> ({{c.phone}}) did not return <b>{{c.title}}</b> · {{c.ts}}</p><p>{{c.text}}</p></div>{% else %}<div class=card>No complaints. 🎉</div>{% endfor %}"""),
"missing.html": P("""<form class=card method=get><input name=q value="{{s}}" placeholder="🔎 Search missing items"><button>Search</button></form>
<div class=card><h3>Lost something?</h3><form method=post enctype=multipart/form-data><input name=title placeholder="Item lost" required><input name=place placeholder="Where lost"><textarea name=descr placeholder="Details"></textarea><input type=file name=photo accept="image/*"><button>Post</button></form></div>
{% for m in ms %}<div class=card><h3>{{m.title}}</h3><p>{{m.descr}} · {{m.place}} · {{m.ts}}</p><small>Contact {{m.name}}: {{m.phone}}</small>{% if m.photo %}<br><img src="/static/uploads/{{m.photo}}" width=150>{% endif %}</div>{% endfor %}"""),
"help.html": P("""<h2>❓ RBR Help Desk</h2><div class=card><h3>How RBR works</h3><ol class=steps><li><b>Register</b> with your name, phone, email and a clear college ID. Only campus members can enter.</li><li><b>Upload</b> an item with brand, purchase date, rent per day and a demo video (electrical items must pass a working test).</li><li><b>Choose Rent or Borrow</b> on any item. Rent costs Rs. per day, Borrow is free for up to 7 days.</li><li>The owner <b>accepts</b> one request.</li><li>The renter enters the <b>number of days</b>; the chat opens and the item is hidden from the site.</li><li>You get <b>reminders</b> before the deadline.</li><li>Return the item. The owner clicks <b>Received</b>; the item shows on RBR again.</li><li>The renter gets a popup to <b>review</b> the item.</li></ol></div>
<div class=card><h3>Common questions</h3>
<details><summary>Who can use RBR?</summary>Only registered students with a valid college ID.</details>
<details><summary>What is the difference between Rent and Borrow?</summary>Rent is paid per day (up to 30 days). Borrow is free for short use (up to 7 days). You see them in separate dashboards.</details>
<details><summary>Where do I see my requests?</summary>Open the Rent or Borrow dashboard from the bottom bar. It has requests on your items and your own requests.</details>
<details><summary>Why can't I see an item any more?</summary>It is currently rented out. It appears again when the owner clicks Received.</details>
<details><summary>When will I get a reminder?</summary>One day before the deadline and after the deadline is over, at the top of every page.</details>
<details><summary>What if someone does not return my item?</summary>Go to Complaints, post it with the handover photo. It is shown to everyone as a suspect and the campus police are informed.</details>
<details><summary>I lost something on campus.</summary>Post it in Missing. Others can search and contact you.</details>
<details><summary>Is it safe?</summary>Meet in public campus places, test the item first, agree on return date in chat and take the handover photo.</details></div>""")}
